    ('21a181ef-2027-4c76-a8a4-3e59a0b1e51b'::uuid, 'period_start', '-2100', '-4500', 'fields-wd1-2026-09-26d-s004-rollback:21a181ef-2027-4c76-a8a4-3e59a0b1e51b:period_start', 'rollback of fields-wd1-2026-09-26d-s004: period_start ''-4500'' restored on Chamaizi', '[{"source": "http://www.travel-to-crete.com/page.php?page_id=243", "url": "http://www.travel-to-crete.com/page.php?page_id=243", "quote": "LINKS TERMS CRETE LASITHI CHAMAIZI On a conical hill called Souvloto Mouri lies the only known oval house of the Middle Minoan Ia period (2100-2000 B.C.).", "outcome": "found"}, {"source": "https://oas.aegeansolutions.com/en/listar-listing/οικισμός-χαμέζι/", "url": "https://oas.aegeansolutions.com/en/listar-listing/οικισμός-χαμέζι/", "quote": "20th century BC) and was built on the site of older buildings dating back to the Early Minoan period.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0187)", "decision": "replace", "status": "MISSING", "reasoning": "Travel to Crete dates the oval house to the Middle Minoan IA period (2100-2000 BC), and Aegean Solutions to the 20th century BC, on top of Early Minoan buildings; the start lies in 3000 - 1500 BC, not in 4500 - 3000 BC.", "value_page": null}]'::jsonb),
