    ('221d4702-9626-4430-a71f-d5b70bcb9d4e'::uuid, 'period_start', '-1400', '-4500', 'fields-wd1-2026-09-26d-s004-rollback:221d4702-9626-4430-a71f-d5b70bcb9d4e:period_start', 'rollback of fields-wd1-2026-09-26d-s004: period_start ''-4500'' restored on Naveta Biniac', '[{"source": "https://www.menorcatalayotica.info/en/Western_naveta_of_Biniac/14366", "url": "https://www.menorcatalayotica.info/en/Western_naveta_of_Biniac/14366", "quote": "The navetas are funerary sepulchres where collective burials were carried out towards the end of the Bronze Age (1400-1000 BC). The Western Naveta of Biniac is not the most monumental in Menorca, but it is relatively well preserved.", "outcome": "found"}, {"source": "https://menorcatrip.com/navetas-de-biniac/", "url": "https://menorcatrip.com/navetas-de-biniac/", "quote": "se conservan dos navetas de enterramiento colectivo de planta circular que fueron utilizadas entre los años 1400 – 1000 a. C.", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Naveta_von_Biniac_(West)", "url": "https://de.wikipedia.org/wiki/Naveta_von_Biniac_(West)", "quote": "1400 bis 1000 v. Chr.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0018)", "decision": "replace", "status": "MISSING", "reasoning": "The stored point lies about 120 m from the Western naveta of Biniac (Wikidata Q28166715), one of the two circular funerary navetas at Biniac-l''Argentina. The Consell Insular''s Menorca Talaiòtica agency dates it to 1400-1000 BC, as do menorcatrip.com for both Biniac navetas and German Wikipedia. That puts the start in the 1500-500 BC bucket, not 4500-3000 BC as stored, so the field is replaced by -1400.", "value_page": null}]'::jsonb),
