    ('22bc5858-875a-4603-b94a-866aaf0a14e1'::uuid, 'period_start', '-1500', '-3000', 'fields-wd1-2026-09-26d-s004-rollback:22bc5858-875a-4603-b94a-866aaf0a14e1:period_start', 'rollback of fields-wd1-2026-09-26d-s004: period_start ''-3000'' restored on Stratonikeia Ancient City', '[{"source": "https://archiv.chnt.at/archaeological-conservation-works-of-stratonikeia-ancient-site/", "url": "https://archiv.chnt.at/archaeological-conservation-works-of-stratonikeia-ancient-site/", "quote": "Stratonikeia, inhabited continuously from the Late Bronze Age (1500 BC) to the present day, is one of the most important city-states in inner Caria.", "outcome": "found"}, {"source": "https://www.ardatunca.net/post/stratonikeia-a-layer-of-civilization-extending-from-caria-to-the-present-day", "url": "https://www.ardatunca.net/post/stratonikeia-a-layer-of-civilization-extending-from-caria-to-the-present-day", "quote": "archaeological evidence indicates that continuous settlement in and around Stratonikeia can be traced back to the Late Bronze Age, around 1500 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0020)", "decision": "replace", "status": "MISSING", "reasoning": "The CHNT conservation paper on the site and an independent article date the start of settlement at Stratonikeia to the Late Bronze Age, c. 1500 BC, and the Turkish Ministry of Culture pages likewise say the excavations show settlement from the Late Bronze Age; no source dates it to 3000 BC, so the start moves to c. 1500 BC (1500 - 500 BC bucket).", "value_page": null}]'::jsonb),
    ('22bc5858-875a-4603-b94a-866aaf0a14e1'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Stratonicea_(Caria)', 'https://whc.unesco.org/en/tentativelists/6041/', 'fields-wd1-2026-09-26d-s004-rollback:22bc5858-875a-4603-b94a-866aaf0a14e1:source_url', 'rollback of fields-wd1-2026-09-26d-s004: source_url ''https://whc.unesco.org/en/tentativelists/6041/'' restored on Stratonikeia Ancient City', '[{"source": "https://en.wikipedia.org/wiki/Stratonicea_(Caria)", "url": "https://en.wikipedia.org/wiki/Stratonicea_(Caria)", "quote": "In early Seleucid times, Stratonikeia was a member of the Chrysaorian League, a confederation of Carian towns.", "outcome": "found"}, {"source": "https://archiv.chnt.at/archaeological-conservation-works-of-stratonikeia-ancient-site/", "url": "https://archiv.chnt.at/archaeological-conservation-works-of-stratonikeia-ancient-site/", "quote": "Stratonicea was one of the most important towns in the interior of Caria, Anatolia The site is now located at the village of Eskihisar, 7 kilometers west of the district of Yatağan in the province of Muğla.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0020)", "decision": "replace", "status": "MISSING", "reasoning": "The stored UNESCO tentative-list page is behind a bot challenge; the English Wikipedia article Stratonicea (Caria) is about this very city at Eskihisar (its coordinates match the stored point), and the CHNT conservation paper independently names Stratonicea and places it at Eskihisar near Yatağan.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Stratonicea (Caria)", "unreadable": false, "wikibase_item": "Q1361187"}}]'::jsonb),
